import json,sys,glob,os
p=os.path.expandvars('\$CLAUDE_JOB_DIR/tmp/nebius/job-h100-plain-lr2x.json')
import pathlib
files=sorted(glob.glob(os.path.expandvars('\$CLAUDE_JOB_DIR/tmp/nebius/job-*lr2x*.json')) or glob.glob(os.path.expandvars('\$CLAUDE_JOB_DIR/tmp/nebius/job-*.json')))
d=json.load(open(files[-1]))
def walk(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items(): walk(v,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path+f'[{i}]')
    else:
        s=str(o); print(path, '=', (s[:80]+'...') if len(s)>80 else s)
print(files[-1]); walk(d)
"

